+    );
+    assert!(
+        patch_agent
+            .lines
+            .iter()
+            .any(|line| line == "follow-up reply")
+    );
+    assert!(backend.sends().iter().any(|(target, prompt)| {
+        target == &agent_id && prompt == "add another change"
+    }));
